fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // Assume `first` is non-empty, as per problem statement.
    let n = first.len();
    assert!(n >= 1, "The first array must be non-empty");

    // Prepare a new Vec with the exact needed capacity
    // (all but last of `first`, then all of `second`).
    let mut result = Vec::with_capacity(n - 1 + second.len());

    // Take all elements of `first` except its last one.
    result.extend_from_slice(&first[..n - 1]);

    // Append all elements of `second`.
    result.extend_from_slice(second);

    result
}

